    // ---------- 历史冻结快照 ----------

    @Test
    void history_keepsFrozenLimitAndTwoDisposersPerVersion() throws Exception {
        String batchKey = newBatch("0.500");
        passTests(batchKey);
        // v1 超限，双处置解除
        submitYield(batchKey, "RY-V1", "100.000", "90.000", "8.000", "1.000", 201);
        dispose(batchKey, "disp-a", 1, "CK-D1", 201);
        dispose(batchKey, "disp-b", 1, "CK-D2", 201);
        // v2 再次超限，无处置
        submitYield(batchKey, "RY-V2", "100.000", "90.000", "7.000", "1.000", 201);

        JsonNode history = historyYields(batchKey);
        assertEquals(2, history.size());

        JsonNode v1 = history.get(0);
        assertEquals(1, v1.path("version").asInt());
        assertEquals("1.000", v1.path("deviation").asText());
        // 历史保留计算所用上限快照
        assertEquals("0.500", v1.path("limit").asText());
        assertEquals("DISPOSED", v1.path("gateStatus").asText());
        assertEquals(List.of("disp-a", "disp-b"), disposers(v1));

        JsonNode v2 = history.get(1);
        assertEquals(2, v2.path("version").asInt());
        assertEquals("2.000", v2.path("deviation").asText());
        assertEquals("EXCEEDED_PENDING", v2.path("gateStatus").asText());
        assertEquals(0, v2.path("disposers").size());

        // 批次当前门禁只认最新版本：v2 待处置，不能放行
        assertEquals("EXCEEDED_PENDING", currentYield(batchKey).path("gateStatus").asText());
        approve(batchKey, "qa-1", "QUALITY", "CK-Q1", 422);

        // 每个版本的冻结上限独立落库
        Integer snapshotRows = jdbc.queryForObject(
                "SELECT COUNT(*) FROM yield_reconciliation WHERE batch_key = ? AND deviation_limit = 0.500",
                Integer.class, batchKey);
        assertEquals(2, snapshotRows);
    }

